{
  "DrugInformation": [],
  "FormularyAbbreviations": [
    {
      "Acronym": "PA",
      "Expansion": "Prior Authorization",
      "Explanation": "Our plan requires you or your prescriber to get prior authorization for certain drugs. This means that you will need to get approval from our plan before you fill your prescriptions. If you don't get approval, our plan may not cover the drug."
    },
    {
      "Acronym": "QL",
      "Expansion": "Quantity Limits",
      "Explanation": "For certain drugs, our plan limits the amount of the drug that our plan will cover. For example, our plan provides 18 tablets per prescription for rizatriptan 5mg. This may be in addition to a standard one-month or three-month supply."
    },
    {
      "Acronym": "ST",
      "Expansion": "Step Therapy",
      "Explanation": "In some cases, our plan requires you to first try certain drugs to treat your medical condition before we will cover another drug for that condition. For example, if Drug A and Drug B both treat your medical condition, our plan may not cover Drug B unless you try Drug A first. If Drug A does not work for you, our plan will then cover Drug B."
    },
    {
      "Acronym": "OTC",
      "Expansion": "Over-the-counter drugs",
      "Explanation": "OTC drugs are non-prescription drugs that are not normally covered by a Medicare Prescription Drug Plan. Our plan pays for certain OTC drugs. This includes OTC drugs like: vitamins, decongestants, antihistamines, pain relievers (acetaminophen, ibuprofen, aspirin), and supplements. Our plan will provide these OTC drugs at no cost to you. The cost to our plan of these OTC drugs will not count toward your total Part D drug costs."
    }
  ]
}

